originalCss:
:root{--bg:#07111e;--panel:#0c1a2e;--line:#1f3354;--text:#e6eefc;--dim:#c7d6ec;--faint:#9cb0cf;--accent:#7c9eff;--sb:300px;--ok:#4ade80;--warn:#fbbf24;--note:#7c9eff}
*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:24px;overflow-x:hidden}
body{margin:0;background:var(--bg);color:var(--text);font-family:"Noto Sans JP","Hiragino Kaku Gothic ProN","Yu Gothic",Meiryo,sans-serif;font-size:16px;line-height:1.85;overflow-x:hidden}
a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}
.sidebar{position:fixed;left:0;top:0;bottom:0;width:var(--sb);background:#050d18;border-right:1px solid var(--line);overflow-y:auto;padding:22px 14px 40px;z-index:30}
.sb-title{font-size:12px;letter-spacing:.08em;color:var(--faint);margin:0 8px 14px}
.sidebar ul{list-style:none;margin:0;padding:0}.sidebar li{margin:0}
.nav-h2{display:block;padding:6px 10px;border-radius:8px;color:var(--dim);font-size:13.5px;font-weight:600;line-height:1.5}
.nav-h3{display:block;padding:3px 10px 3px 22px;color:var(--faint);font-size:12.5px;line-height:1.5;border-left:2px solid transparent;margin-left:10px}
.sidebar a:hover{background:#0c1a2e;text-decoration:none;color:#fff}
.sidebar a.active{color:#fff;background:#12274a}.nav-h3.active{border-left-color:var(--accent);background:transparent;color:var(--accent)}
.main{margin-left:var(--sb);padding:0 56px 80px}
.hero{position:relative;padding:56px 0 30px;border-bottom:1px solid var(--line);margin-bottom:34px;overflow:hidden}
.hero::before{content:"";position:absolute;right:-120px;top:-140px;width:520px;height:420px;background:radial-gradient(closest-side,rgba(124,158,255,.22),transparent);pointer-events:none}
.eyebrow{display:inline-block;padding:4px 14px;border:1px solid #2c4a86;border-radius:999px;background:#0e1f3d;color:var(--accent);font-size:12.5px;font-weight:700;letter-spacing:.04em}
.hero-title{font-size:28px;font-weight:800;color:#fff;line-height:1.4;margin:16px 0 8px}
.hero-sub{color:var(--dim);margin:0 0 22px;font-size:15px}
.hero-meta{display:flex;flex-wrap:wrap;margin-top:6px}
.hm{display:flex;flex-direction:column;padding:2px 22px;border-right:1px solid var(--line)}.hm:first-child{padding-left:0}.hm:last-child{border-right:0}
.hm-l{font-size:11px;letter-spacing:.08em;color:var(--faint)}.hm-v{font-size:14.5px;color:var(--text)}
.hero-note{margin-top:16px;font-size:13.5px;color:var(--faint)}
h2{font-size:23px;font-weight:800;color:#fff;margin:56px 0 18px;padding:14px 0 0;border-top:1px solid var(--line);line-height:1.5}
.main>h2:first-of-type{border-top:0;margin-top:20px}
h3{font-size:18.5px;font-weight:700;color:#dfe9ff;margin:34px 0 12px;padding-left:12px;border-left:3px solid var(--accent);line-height:1.55}
h4{font-size:16px;color:var(--dim);margin:22px 0 8px}
p{margin:12px 0;color:var(--text)}ul,ol{padding-left:1.4em}li{margin:4px 0}
strong{color:#fff;font-weight:700}
code{font-family:"JetBrains Mono",Consolas,Menlo,monospace;font-size:.88em;background:#0f2038;border:1px solid #1c3157;border-radius:6px;padding:1px 6px;color:#cfe0ff;overflow-wrap:anywhere}
pre{background:#050d18;border:1px solid var(--line);border-radius:12px;padding:16px 18px;overflow-x:auto;line-height:1.65}
pre code{background:transparent;border:0;padding:0;color:#d6e3ff;font-size:13.5px;overflow-wrap:normal}
.tk-c{color:#7f93b5;font-style:italic}.tk-k{color:#8fb0ff}.tk-s{color:#7ee0b0}.tk-n{color:#ffcf7a}
.table-scroll{overflow-x:auto;margin:16px 0;border:1px solid var(--line);border-radius:12px;background:var(--panel)}
table{border-collapse:collapse;width:100%;font-size:14.5px}
th{background:#112445;color:#fff;text-align:left;font-weight:700;white-space:nowrap}
th,td{padding:10px 14px;border-bottom:1px solid var(--line);vertical-align:top}
tr:last-child td{border-bottom:0}tbody tr:nth-child(even){background:#0a1727}
td a{overflow-wrap:anywhere;word-break:break-all}
.mermaid-diagram{display:block;overflow-x:auto;border:1px solid var(--line);border-radius:14px;background:#08162a;padding:22px 18px;margin:20px 0}
.mermaid-diagram svg{display:block;margin-left:auto;margin-right:auto;max-width:none}
.mermaid-diagram p{color:inherit;margin:0}
.callout{display:flex;gap:12px;border:1px solid var(--line);border-left-width:4px;border-radius:12px;padding:12px 16px;margin:18px 0;background:var(--panel)}
.callout-icon{font-size:18px;line-height:1.7}.callout-body{min-width:0;flex:1}.callout-body p{margin:4px 0}
.callout-title{font-weight:800;color:#fff;margin-bottom:2px}
.callout-practice{border-left-color:var(--ok);background:#0a1e1b}.callout-warn{border-left-color:var(--warn);background:#1f1a0a}.callout-note{border-left-color:var(--note)}
.checklist-card{border:1px solid var(--line);background:var(--panel);border-radius:14px;padding:14px 18px;margin:18px 0}
.checklist label{display:flex;gap:10px;align-items:flex-start;cursor:pointer;width:100%}.checklist{list-style:none;padding:0;margin:10px 0 0}.checklist li{padding:6px 0;border-bottom:1px dashed #1a2d4d}.checklist li:last-child{border-bottom:0}
.cb{margin-top:8px;width:17px;height:17px;accent-color:var(--accent);flex:none;cursor:pointer}
.checklist-progress{display:flex;align-items:center;gap:12px;font-size:13px;color:var(--dim)}
.cp-bar{flex:1;height:8px;background:#12233d;border-radius:99px;overflow:hidden}.cp-fill{height:100%;width:0;background:linear-gradient(90deg,#4f78ff,#7c9eff);transition:width .25s}
.page-footer{margin-top:60px;padding-top:18px;border-top:1px solid var(--line);color:var(--faint);font-size:13.5px}
.menu-btn{display:none;position:fixed;top:12px;left:12px;z-index:50;width:42px;height:42px;border-radius:10px;border:1px solid var(--line);background:#0c1a2e;color:#fff;font-size:20px;cursor:pointer}
@media(max-width:960px){.sidebar{transform:translateX(-100%);transition:transform .25s}.sidebar.open{transform:none}.main{margin-left:0;padding:0 18px 60px}.menu-btn{display:block}.hero{padding-top:70px}.hm{padding:6px 0;border-right:0;border-bottom:1px solid var(--line);width:100%}.hm:last-child{border-bottom:0}.hero-title{font-size:23px}}
